    fn sqlite_file_contents(coven_home: &Path) -> anyhow::Result<Vec<Option<Vec<u8>>>> {
        ["coven.sqlite3", "coven.sqlite3-wal", "coven.sqlite3-shm"]
            .into_iter()
            .map(|file_name| {
                let path = coven_home.join(file_name);
                if path.exists() {
                    Ok(Some(std::fs::read(path)?))
                } else {
                    Ok(None)
                }
            })
            .collect()
    }

